import json
with open('/root/DATA/products/PersonalizeForce.json','r') as f:
    data = json.load(f)
print('Top-level keys:', list(data.keys()))
for k in data.keys():
    if isinstance(data[k], list):
        print(f'{k}: list with {len(data[k])} items')
    elif isinstance(data[k], dict):
        print(f'{k}: dict with {len(data[k])} keys')
    else:
        print(f'{k}: {type(data[k]).__name__}')
"

